<?php
namespace App\Http\Controllers;
use App\Services\Identity;
use App\Support\Json;
use Illuminate\Support\Facades\DB;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
final class SupportRecoveryController extends Controller {
    public function request(Request $r){$d=$r->validate(['ticket_id'=>'required|uuid','email'=>'required|email:rfc|max:254']);$t=DB::table('support_tickets')->where('id',$d['ticket_id'])->where('reply_email',strtolower($d['email']))->first();if(!$t)return response()->json(['state'=>'if_ticket_matches_instructions_sent']);$challenge=app(Identity::class)->issueOtp($d['email'],'support_recovery',$t->user_id);return response()->json(['state'=>'if_ticket_matches_instructions_sent','challenge_id'=>$challenge['challenge_id'],'ticket_id'=>$t->id]);}
    public function verify(Request $r){$d=$r->validate(['ticket_id'=>'required|uuid','challenge_id'=>'required|uuid','code'=>'required|string|max:12']);$c=app(Identity::class)->consumeOtp($d['challenge_id'],$d['code'],'support_recovery');$t=DB::table('support_tickets')->where('id',$d['ticket_id'])->where('user_id',$c->user_id)->where('reply_email',$c->email)->first();if(!$t)Json::fail('invalid_support_recovery',401);$token=bin2hex(random_bytes(32));DB::table('support_access')->insert(['id'=>(string)Str::uuid(),'ticket_id'=>$t->id,'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addMinutes(15)]);return response()->json(['support_token'=>$token,'ticket_id'=>$t->id,'expires_in'=>900,'scope'=>'this_support_ticket_only']);}
    private function access(Request $r,string $id): object {$a=DB::table('support_access')->where('ticket_id',$id)->where('token_hash',hash('sha256',$r->bearerToken()??''))->where('expires_at','>',now())->first();if(!$a)Json::fail('invalid_support_access',401);return $a;}
    public function view(Request $r,string $id){$this->access($r,$id);$t=DB::table('support_tickets')->where('id',$id)->first(['id','category','title','description','state','created_at']);return response()->json(['ticket'=>$t,'replies'=>DB::table('support_replies')->where('ticket_id',$id)->get(['body','created_at'])]);}
    public function reply(Request $r,string $id){$a=$this->access($r,$id);$d=$r->validate(['body'=>'required|string|max:10000']);$key=$r->header('Idempotency-Key','');if(!preg_match('/^[A-Za-z0-9_.:-]{16,128}$/D',$key))Json::fail('idempotency_key_required',400);return DB::transaction(function()use($id,$a,$key,$d){$t=DB::table('support_tickets')->where('id',$id)->lockForUpdate()->first();if(!$t||$t->state==='closed')Json::fail('ticket_closed',409);$hash=hash('sha256',$a->id.'|'.$key);$prior=DB::table('support_replies')->where('reply_key',$hash)->first();if($prior&&$prior->body!==$d['body'])Json::fail('idempotency_key_conflict',409);if(!$prior){DB::table('support_replies')->insert(['ticket_id'=>$id,'reply_key'=>$hash,'body'=>$d['body'],'created_at'=>now()]);DB::table('support_tickets')->where('id',$id)->update(['state'=>'open','updated_at'=>now()]);\App\Jobs\NotifySupport::dispatch($id)->afterCommit();}return response()->json(['reply_saved'=>true]);});}
}
